#!/usr/bin/env bash
# ============================================================================
# ALL-IN-ONE EXP11–EXP15 TRAINING + EVALUATION
#
# This single script:
#   1. Installs the required PER trainer, R2-offline trainer, and R2-aware evaluator.
#   2. Trains Exp11, Exp12, Exp13 for 6 total epochs each.
#   3. Trains Exp15 first, then Exp14, for 10 total epochs each.
#   4. Verifies that all five requested checkpoints exist.
#   5. Evaluates all five checkpoints with one common R2-aware evaluation suite.
#
# It is restart-safe:
#   - completed experiments are skipped;
#   - partial experiments resume from checkpoint.pt or the latest epoch checkpoint;
#   - an independent training failure does not prevent later experiments from running;
#   - evaluation starts only when all five final checkpoints exist.
#
# Exp13 is defined as:
#   Exp12 + uniform temporal weighting instead of lambda weighting.
# ============================================================================

set -u
set -o pipefail

ROOT_DIR="${ROOT_DIR:-/home/jovyan/smac-jepa-wm}"
STAMP="$(date +%Y%m%d_%H%M%S)"
LOG_DIR="${ROOT_DIR}/runs/exp11_to_exp15_all_in_one_logs_${STAMP}"
TMP_DIR="$(mktemp -d)"

cleanup() {
  rm -rf "$TMP_DIR"
}
trap cleanup EXIT

cd "$ROOT_DIR" || {
  echo "ERROR: cannot enter repository: $ROOT_DIR"
  exit 1
}

mkdir -p smac_jepa "$LOG_DIR"

echo "============================================================"
echo "Exp11–Exp15 all-in-one pipeline"
echo "Repository: $ROOT_DIR"
echo "Logs:       $LOG_DIR"
echo "Started:    $(date)"
echo "============================================================"

# ----------------------------------------------------------------------------
# Install embedded Python files safely.
# ----------------------------------------------------------------------------

cat > "$TMP_DIR/train_markov_rollout_rnn_visibility_seqmem_per.py.b64" <<'__PER_B64__'
