base64 -d   "$TMP_DIR/train_markov_rollout_rnn_visibility_seqmem_per.py.b64"   > "$TMP_DIR/train_markov_rollout_rnn_visibility_seqmem_per.py"

base64 -d   "$TMP_DIR/train_markov_rollout_rnn_visibility_seqmem_r2offline.py.b64"   > "$TMP_DIR/train_markov_rollout_rnn_visibility_seqmem_r2offline.py"

base64 -d   "$TMP_DIR/eval_rnn_seqmem_dreamer_probe_r2aware.py.b64"   > "$TMP_DIR/eval_rnn_seqmem_dreamer_probe_r2aware.py"

python -m py_compile   "$TMP_DIR/train_markov_rollout_rnn_visibility_seqmem_per.py"   "$TMP_DIR/train_markov_rollout_rnn_visibility_seqmem_r2offline.py"   "$TMP_DIR/eval_rnn_seqmem_dreamer_probe_r2aware.py" || {
    echo "ERROR: embedded Python files failed compilation."
    exit 1
  }

install -m 0644   "$TMP_DIR/train_markov_rollout_rnn_visibility_seqmem_per.py"   smac_jepa/train_markov_rollout_rnn_visibility_seqmem_per.py

install -m 0644   "$TMP_DIR/train_markov_rollout_rnn_visibility_seqmem_r2offline.py"   smac_jepa/train_markov_rollout_rnn_visibility_seqmem_r2offline.py

install -m 0644   "$TMP_DIR/eval_rnn_seqmem_dreamer_probe_r2aware.py"   ./eval_rnn_seqmem_dreamer_probe_r2aware.py

PER_MODULE="smac_jepa.train_markov_rollout_rnn_visibility_seqmem_per"
R2_MODULE="smac_jepa.train_markov_rollout_rnn_visibility_seqmem_r2offline"
EVALUATOR="./eval_rnn_seqmem_dreamer_probe_r2aware.py"

LD_LIBRARY_PATH="" python -m "$PER_MODULE" --help >/dev/null || {
  echo "ERROR: PER trainer could not be imported."
  exit 1
}

LD_LIBRARY_PATH="" python -m "$R2_MODULE" --help >/dev/null || {
  echo "ERROR: R2-offline trainer could not be imported."
  exit 1
}

LD_LIBRARY_PATH="" python "$EVALUATOR" --help >/dev/null || {
  echo "ERROR: R2-aware evaluator could not be imported."
  exit 1
}

echo "Installed and verified all embedded Python files."

# ----------------------------------------------------------------------------
# Restart helpers.
# ----------------------------------------------------------------------------

target_checkpoint() {
  local run_dir="$1"
  local epoch="$2"
  printf "%s/checkpoint_epoch_%03d.pt" "$run_dir" "$epoch"
}

latest_checkpoint() {
  local run_dir="$1"

  if [[ -f "${run_dir}/checkpoint.pt" ]]; then
    printf "%s\n" "${run_dir}/checkpoint.pt"
    return 0
  fi

  local latest=""
  latest="$(
    find "$run_dir" -maxdepth 1 -type f -name 'checkpoint_epoch_*.pt'       2>/dev/null | sort | tail -n 1
  )"

  if [[ -n "$latest" ]]; then
    printf "%s\n" "$latest"
    return 0
  fi

  return 1
}

run_logged() {
  local name="$1"
  shift

  local log_file="${LOG_DIR}/${name}.log"
  local status_file="${LOG_DIR}/${name}.status"

  echo
  echo "============================================================"
  echo "START: $name"
  echo "TIME:  $(date)"
  echo "LOG:   $log_file"
  echo "============================================================"

  "$@" 2>&1 | tee "$log_file"
  local code=${PIPESTATUS[0]}
  printf "%s\n" "$code" > "$status_file"

  echo "============================================================"
  echo "END:   $name"
  echo "CODE:  $code"
  echo "TIME:  $(date)"
  echo "============================================================"

  # Independent experiments continue even when this one fails.
  return 0
}

# ----------------------------------------------------------------------------
# Exp11–Exp13: six total epochs.
# ----------------------------------------------------------------------------

run_per_experiment() {
  local label="$1"
  local out_dir="$2"
  local wandb_name="$3"
  local temporal_loss="$4"
  local action_conditioned="$5"

  local final_checkpoint
  final_checkpoint="$(target_checkpoint "$out_dir" 6)"

  if [[ -f "$final_checkpoint" ]]; then
    echo "SKIP $label: $final_checkpoint already exists"
    return 0
  fi

  local resume_args=()
  local checkpoint=""
  if checkpoint="$(latest_checkpoint "$out_dir")"; then
    resume_args=(--resume "$checkpoint")
    echo "$label will resume from $checkpoint"
  fi

  local action_args=()
  if [[ "$action_conditioned" == "true" ]]; then
    action_args=(--action-conditioned-memory)
  fi

  run_logged "$label"     env LD_LIBRARY_PATH="" python -m "$PER_MODULE"       --manifest splits/generated_seed4_mapdims_only.json       --split train       --out-dir "$out_dir"       --model-size default       --epochs 6       --batch-size 16       --num-workers 4       --rollout-window 20       --rollout-horizon 5       --window-mode random       --samples-per-epoch 50000       --enemy-visibility-mask       --enemy-sight-range 9.0       --temporal-loss "$temporal_loss"       --td-lambda 0.9       --sigreg-weight 0.01       --decoder-weight 0.01       --presence-weight 0.01       --rollout-memory-dim 128       --target-mode full       "${action_args[@]}"       --one-step-weight 0.5       --sample-prioritized       --priority-alpha 0.4       --priority-uniform-mix 0.7       --priority-ema-beta 0.95       --priority-warmup-epochs 2       --priority-score pred_loss       "${resume_args[@]}"       --grad-clip 1.0       --device cuda       --amp       --wandb       --wandb-project SMAC-JEPA-losses       --wandb-name "$wandb_name"
}

run_per_experiment   "01_exp11_per_lambda_e6"   "runs/rnn_seqmem_exp11_per_onestep_full_h5"   "rnn-seqmem-exp11-per-onestep-full-h5-e6"   "lambda"   "false"

run_per_experiment   "02_exp12_action_memory_per_lambda_e6"   "runs/rnn_seqmem_exp12_action_memory_per_onestep_full_h5"   "rnn-seqmem-exp12-action-memory-per-onestep-full-h5-e6"   "lambda"   "true"

run_per_experiment   "03_exp13_action_memory_per_uniform_e6"   "runs/rnn_seqmem_exp13_action_memory_per_uniform_full_h5"   "rnn-seqmem-exp13-action-memory-per-uniform-full-h5-e6"   "uniform"   "true"

# ----------------------------------------------------------------------------
# Exp15 then Exp14: ten total epochs.
# ----------------------------------------------------------------------------

run_r2_experiment() {
  local label="$1"
  local out_dir="$2"
  local wandb_name="$3"
  local use_sigreg="$4"

  local final_checkpoint
  final_checkpoint="$(target_checkpoint "$out_dir" 10)"

  if [[ -f "$final_checkpoint" ]]; then
    echo "SKIP $label: $final_checkpoint already exists"
    return 0
  fi

  local resume_args=()
  local checkpoint=""
  if checkpoint="$(latest_checkpoint "$out_dir")"; then
    resume_args=(--resume "$checkpoint")
    echo "$label will resume from $checkpoint"
  fi

  local sigreg_args=(--sigreg-weight 0.0)
  if [[ "$use_sigreg" == "true" ]]; then
    sigreg_args=(
      --sigreg-weight 0.01
      --r2-sigreg-divide-by-dim
      --r2-sigreg-knots 17
      --r2-sigreg-num-proj 1024
      --r2-sigreg-proj-chunk 64
      --r2-sigreg-max-samples 0
    )
  fi

  run_logged "$label"     env LD_LIBRARY_PATH="" python -m "$R2_MODULE"       --manifest splits/generated_seed4_mapdims_only.json       --split train       --out-dir "$out_dir"       --model-size default       --epochs 10       --batch-size 16       --num-workers 4       --rollout-window 20       --rollout-horizon 5       --window-mode random       --samples-per-epoch 50000       --enemy-visibility-mask       --enemy-sight-range 9.0       --temporal-loss lambda       --td-lambda 0.9       --r2-dyn-scale 1.0       --r2-rep-scale 0.1       --r2-barlow-scale 0.05       --r2-barlow-lambda 0.0005       --r2-latent-normalize       --lr-warmup-steps 1000       "${sigreg_args[@]}"       --decoder-weight 0.01       --presence-weight 0.01       --rollout-memory-dim 128       --target-mode full       --action-conditioned-memory       --one-step-weight 0.5       "${resume_args[@]}"       --grad-clip 1.0       --device cuda       --amp       --wandb       --wandb-project SMAC-JEPA-losses       --wandb-name "$wandb_name"
}

# Exp15 runs first, as previously requested.
run_r2_experiment   "04_exp15_r2offline_sigreg_e10"   "runs/rnn_seqmem_exp15_r2offline_sigreg_full_h5"   "rnn-seqmem-exp15-r2offline-sigreg-full-h5"   "true"

run_r2_experiment   "05_exp14_r2offline_e10"   "runs/rnn_seqmem_exp14_r2offline_full_h5"   "rnn-seqmem-exp14-r2offline-full-h5"   "false"

# ----------------------------------------------------------------------------
# Require every final checkpoint before starting evaluation.
# ----------------------------------------------------------------------------

EXP11_CKPT="runs/rnn_seqmem_exp11_per_onestep_full_h5/checkpoint_epoch_006.pt"
EXP12_CKPT="runs/rnn_seqmem_exp12_action_memory_per_onestep_full_h5/checkpoint_epoch_006.pt"
EXP13_CKPT="runs/rnn_seqmem_exp13_action_memory_per_uniform_full_h5/checkpoint_epoch_006.pt"
EXP15_CKPT="runs/rnn_seqmem_exp15_r2offline_sigreg_full_h5/checkpoint_epoch_010.pt"
EXP14_CKPT="runs/rnn_seqmem_exp14_r2offline_full_h5/checkpoint_epoch_010.pt"

missing=()
for checkpoint in   "$EXP11_CKPT"   "$EXP12_CKPT"   "$EXP13_CKPT"   "$EXP15_CKPT"   "$EXP14_CKPT"
do
  if [[ ! -f "$checkpoint" ]]; then
    missing+=("$checkpoint")
  fi
done

if [[ ${#missing[@]} -gt 0 ]]; then
  echo
  echo "============================================================"
  echo "TRAINING QUEUE FINISHED, BUT EVALUATION WILL NOT START."
  echo "Missing final checkpoints:"
  printf "  %s\n" "${missing[@]}"
  echo
  echo "Inspect logs in:"
  echo "  $LOG_DIR"
  echo
  echo "Rerun this same script after fixing the failed experiment."
  echo "Completed experiments will be skipped automatically."
  echo "============================================================"
  exit 1
fi

# ----------------------------------------------------------------------------
# Combined evaluation.
# ----------------------------------------------------------------------------

EVAL_OUT_DIR="${EVAL_OUT_DIR:-runs/eval_exp11_to_exp15_r2aware_h5}"
EVAL_MAX_BATCHES="${EVAL_MAX_BATCHES:-500}"
DIAGNOSTIC_MAX_BATCHES="${DIAGNOSTIC_MAX_BATCHES:-100}"
PROBE_EPOCHS="${PROBE_EPOCHS:-20}"
PROBE_MAX_BATCHES="${PROBE_MAX_BATCHES:-300}"
PROBE_SAMPLES_PER_EPOCH="${PROBE_SAMPLES_PER_EPOCH:-20000}"
FORCE_EVAL="${FORCE_EVAL:-0}"

mkdir -p "$EVAL_OUT_DIR"
SUMMARY_FILE="${EVAL_OUT_DIR}/eval_seqmem_combined_summary.csv"

if [[ -f "$SUMMARY_FILE" && "$FORCE_EVAL" != "1" ]]; then
  echo
  echo "Evaluation summary already exists:"
  echo "  $SUMMARY_FILE"
  echo "Set FORCE_EVAL=1 to rerun evaluation."
else
  run_logged "06_combined_r2aware_evaluation"     env LD_LIBRARY_PATH="" python "$EVALUATOR"       --manifest splits/generated_seed4_mapdims_only.json       --split eval       --checkpoint "$EXP11_CKPT"       --checkpoint "$EXP12_CKPT"       --checkpoint "$EXP13_CKPT"       --checkpoint "$EXP15_CKPT"       --checkpoint "$EXP14_CKPT"       --out-dir "$EVAL_OUT_DIR"       --batch-size 16       --num-workers 4       --max-batches "$EVAL_MAX_BATCHES"       --diagnostics       --diagnostic-max-batches "$DIAGNOSTIC_MAX_BATCHES"       --eval-rollout-horizon 5       --target-mode full       --window-mode sequential       --probe-decoder       --probe-train-split train       --probe-epochs "$PROBE_EPOCHS"       --probe-max-batches-per-epoch "$PROBE_MAX_BATCHES"       --probe-samples-per-epoch "$PROBE_SAMPLES_PER_EPOCH"       --probe-lr 0.001       --probe-weight-decay 0.00001       --probe-seed 123       --device cuda       --amp
fi

echo
echo "============================================================"
echo "ALL-IN-ONE PIPELINE FINISHED"
echo "TIME: $(date)"
echo
echo "Training logs:"
echo "  $LOG_DIR"
echo
echo "Evaluation directory:"
echo "  $EVAL_OUT_DIR"
echo
echo "Main summary:"
echo "  $SUMMARY_FILE"
echo
echo "Status files:"
for status_file in "$LOG_DIR"/*.status; do
  [[ -e "$status_file" ]] || continue
  printf "  %-48s %s\n"     "$(basename "$status_file" .status)"     "$(cat "$status_file")"
done
echo "============================================================"
